<?php
namespace App\Console\Commands; use Illuminate\Console\Command;
class AuditLegacyAssets extends Command {protected $signature='legacy:audit-assets'; protected $description='Report recovered catalog image paths missing from public/legacy'; public function handle():int{$path=database_path('data/recovered_catalog.json');if(!is_file($path)){$this->error('Catalog JSON missing.');return self::FAILURE;}$data=json_decode(file_get_contents($path),true);$missing=[];$total=0;foreach($data['properties']??[] as $item){foreach((array)data_get($item,'schema.image',[]) as $url){$total++;$rel=ltrim((string)parse_url($url,PHP_URL_PATH),'/');if(!is_file(public_path('legacy/'.$rel)))$missing[$rel]=true;}}$this->info("Referenced property images: {$total}");$this->warn('Missing unique images: '.count($missing));foreach(array_keys($missing) as $m)$this->line($m);return self::SUCCESS;}}
